# {{branding.site_name}} 生产配置 (伪造)
# instance trace: {{instance.canary}}
server:
  port: 8080
  servlet:
    context-path: /{{server.app_context}}
spring:
  datasource:
    url: {{db_dsn}}
    username: {{db_user}}
    password: {{db_password}}
    driver-class-name: com.mysql.jdbc.Driver
  redis:
    host: {{cache_host}}
    port: 6379
    password: {{jwt_secret}}
    database: 3
  servlet:
    multipart:
      max-file-size: 50MB
      location: {{upload_path}}
gov:
  jwt:
    signing-key: {{jwt_secret}}
    expire-seconds: 604800
  oss:
    endpoint: {{oss_endpoint}}
    bucket: {{oss_bucket}}
    access-key-id: {{api_token}}
    access-key-secret: {{app_key}}
  inner-gateway: {{gw_host}}:8443
  file-node: {{file_host}}
management:
  endpoints:
    web:
      exposure:
        include: '*'
logging:
  file:
    name: {{server.log_path}}

